export const codexExecutionLocales = Object.fromEntries(Object.entries(copy).map(([locale, values]) => [locale, Object.fromEntries(keys.map((key, index) => [key, key === 'replyFailed' ? replyFailed[locale] : values[index]]))]))
export function tCodexExecution(key, language) {
  return (codexExecutionLocales[String(language || '').toLowerCase().split('-')[0]] || codexExecutionLocales.en)[key] || codexExecutionLocales.en[key] || key
}
